CREATE TABLE "public"."team_invoice_details" ("id" serial NOT NULL, "team_id" integer NOT NULL, "business_name" text, "address_line1" text, "address_line2" text, "town_city" text, "county" text, "postcode" text, "vat_number" text, "company_registration" text, "email_address" text, PRIMARY KEY ("id") , UNIQUE ("id"), UNIQUE ("team_id"), FOREIGN KEY ("team_id") REFERENCES "public"."teams"("id") ON UPDATE cascade ON DELETE cascade);